<script setup lang="ts">
import { ref,watch,onMounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { user,api,refreshAuth,notification,notify,message,siteName } from './api'
import Icon from './components/Icon.vue'
import IdentityPicker from './components/IdentityPicker.vue'
import ProfileForm from './components/ProfileForm.vue'
const route=useRoute(),router=useRouter(),menu=ref(false),profileReminder=ref(false),reminderBusy=ref(false),reminderError=ref('')
const pageRefreshedAt=new Date()
const pageRefreshedText=new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(pageRefreshedAt)
watch(()=>route.fullPath,()=>{menu.value=false})
watch(()=>[user.value?.id,user.value?.profileCompleted,user.value?.profilePromptSeen],()=>{profileReminder.value=!!user.value&&!user.value.profileCompleted&&!user.value.profilePromptSeen},{immediate:true})
onMounted(async()=>{try{siteName.value=(await api.get('/public/site')).data.name}catch{}})
async function skipReminder(){reminderBusy.value=true;reminderError.value='';try{await api.post('/member/profile/reminder-dismiss');await refreshAuth();profileReminder.value=false}catch(e){reminderError.value=message(e)}finally{reminderBusy.value=false}}
async function logout(){try{await api.post('/auth/logout');await refreshAuth();router.push('/');notify('已退出登录')}catch(e){notify(message(e))}}
</script>
<template><div class="site-shell"><header class="site-header"><div class="header-inner">
<RouterLink to="/" class="brand" @click="menu=false"><img src="/brand/haiyan-bird.svg" alt="" aria-hidden="true"/><span>{{siteName}}<small>HAIYAN · LITERARY SOCIETY</small></span></RouterLink>
<nav :class="{open:menu}" aria-label="主导航"><RouterLink to="/" exact-active-class="active" @click="menu=false">首页</RouterLink><RouterLink to="/explore" active-class="active" @click="menu=false">作品书架</RouterLink><RouterLink to="/collections" active-class="active" @click="menu=false">合集</RouterLink><RouterLink to="/activities" active-class="active" @click="menu=false">征稿与活动</RouterLink><RouterLink to="/about" active-class="active" @click="menu=false">关于</RouterLink><RouterLink v-if="user" to="/account" active-class="active" @click="menu=false">我的书桌</RouterLink><RouterLink v-if="['ADMIN','SUPER_ADMIN'].includes(user?.actorRole||user?.role||'')||(user?.accountType==='PUBLIC'&&['haiyan_editor','haiyan_activity','haiyan_tech'].includes(user?.username||'')&&user?.actorRole!=='RESTRICTED')" to="/admin" active-class="active" @click="menu=false">社务台</RouterLink></nav>
<div class="header-actions"><RouterLink to="/write" class="button small"><Icon name="Feather" :size="16"/><span>写一篇</span></RouterLink><RouterLink v-if="!user" to="/login" class="login-link">登录 / 注册</RouterLink><IdentityPicker v-else/><button class="icon-button mobile-menu" :aria-expanded="menu" aria-label="打开导航" @click="menu=!menu"><Icon :name="menu?'X':'Menu'"/></button></div></div></header>
<main :key="route.path" class="main-content"><RouterView /></main><footer class="site-footer"><nav class="footer-links" aria-label="页脚导航"><RouterLink to="/collections" @click="menu=false">合集</RouterLink><RouterLink to="/activities" @click="menu=false">征稿活动</RouterLink><RouterLink to="/about">关于</RouterLink></nav><div class="footer-identity"><div class="footer-title"><img src="/brand/haiyan-bird.svg" alt="" aria-hidden="true"/><span>海燕传信</span></div><p class="footer-refresh">最后刷新时间：<time :datetime="pageRefreshedAt.toISOString()">{{pageRefreshedText}}</time></p><div class="footer-maintainers"><span>运营维护：</span><img class="footer-seal" src="/brand/haiyan-seal.jpg" alt="海燕文学社标志"/><span class="footer-tech-window" role="img" aria-label="技术部标志"><img src="/brand/tech-department.png" alt="" aria-hidden="true"/></span><span>海燕文学社技术部</span></div></div></footer><Transition name="toast"><div v-if="notification" class="toast" role="status">{{notification}}</div></Transition><div v-if="profileReminder" class="modal-backdrop"><section class="profile-modal" role="dialog" aria-modal="true" aria-labelledby="profile-reminder-title"><h2 id="profile-reminder-title">完善个人资料</h2><p class="quiet-note">可设置账号昵称，头像使用注册时的 QQ 号。</p><ProfileForm @saved="profileReminder=false"/><p v-if="reminderError" class="error-message">{{reminderError}}</p><button class="text-button" :disabled="reminderBusy" @click="skipReminder">稍后设置</button></section></div></div></template>
